"use strict";(self.webpackChunk_otw_web_docusaurus=self.webpackChunk_otw_web_docusaurus||[]).push([[1861],{4051(a){a.exports=JSON.parse('{"title":"Lazy loading\uc774 \uc131\ub2a5\uc744 \ub0ae\ucd9c \uc218\ub3c4 \uc788\uc2b5\ub2c8\ub2e4.","date":"2023-09-13","coverUrl":"/kudzu-based-bench/assets/notion/9b94f1017b38d074.jpg","html":"<p data-notion-block-id=\\"f5c104ed-0ad4-48fc-afbc-2e5c9ea3bafa\\">\uccab\ubc88\uc9f8 \ub274\uc2a4\ub808\ud130\uac00 React\uc5d0 \uce58\uc911\ub418\uc5b4 \uc788\ub294 \uac83 \uac19\uc544\uc11c, \ub2e4\uc591\ud55c FE \uc804\ubc18\uc758 \uc815\ubcf4\ub97c \ub290\ub084 \uc218 \uc788\ub3c4\ub85d \uc5ec\ub7ec\uac00\uc9c0 \uc815\ubcf4\ub97c \uac00\uc838\uc654\uc2b5\ub2c8\ub2e4. \uc774\ubc88\uc8fc\ub3c4 \uc88b\uc740 \uc815\ubcf4\uac00 \ub418\uc5c8\uc73c\uba74 \ud558\ub294 \ubc14\ub78c\uacfc \ud568\uaed8 \ub2e4\uc74c\uc8fc\uc5d0 \ub9cc\ub098\uc694 :)</p><h2 data-notion-block-id=\\"465d6293-2c26-4269-a514-b5976be62bf0\\" id=\\"465d6293-2c26-4269-a514-b5976be62bf0\\">Lazy loading\uc774 \uc131\ub2a5\uc744 \ub0ae\ucd9c \uc218\ub3c4 \uc788\uc2b5\ub2c8\ub2e4.</h2><a href=\\"https://performance.shopify.com/blogs/blog/how-layout-position-impacts-three-big-web-performance-levers\\" class=\\"bookmark-link\\" target=\\"_blank\\" rel=\\"noreferrer\\">https://performance.shopify.com/blogs/blog/how-layout-position-impacts-three-big-web-performance-levers</a><p data-notion-block-id=\\"06a61810-ee1a-4654-9999-8de0ba35fd40\\"><b>\uc2ec\uc724\uc12d</b>: Shopify \uace0\uac1d\uc774 \uc27d\uac8c \ub193\uce60 \uc218 \uc788\ub294 \uc138\uac00\uc9c0 \uc131\ub2a5 \uc774\uc288\uc5d0 \ub300\ud574 \uc18c\uac1c\ud55c \uae00\uc785\ub2c8\ub2e4. \uccab \ubc88\uc9f8\uc778 lazy loading\uc774 \uac00\uc7a5 \ubcf4\ud3b8\uc801\uc73c\ub85c \ubcf4\uc5ec\uc11c \uac00\uc838\uc654\uc2b5\ub2c8\ub2e4. \uc774\uc720\ub3c4 \ub80c\ub354\ub9c1 \ud2b8\ub9ac\ub97c \uadf8\ub824\uac00\uba70 \uc124\uba85\ud574\uc11c \uc774\ud574\ud558\uae30 \uc27d\uad6c\uc694.(CSS \ube44\ub3d9\uae30 \ub85c\ub529/fetchpriority\ub294 Code Spliting/Cross browsing\ub54c\ubb38\uc5d0 \ubcf4\ud3b8\uc801\uc774 \uc544\ub2c8\uae34 \ud569\ub2c8\ub2e4.) \uc694\uc57d\ud558\uc790\uba74 lazy loading\uc744 Large Content(Image)\uc5d0\ub3c4 \uc801\uc6a9\ub420 \uacbd\uc6b0\uc5d0 Chrome\uc758 <a href=\\"https://web.dev/i18n/en/browser-level-image-lazy-loading/#is-there-a-downside-to-lazy-loading-images-that-are-within-the-device-viewport\\">Preload scanner\uc5d0\ub3c4 \uac78\ub9ac\uc9c0\ub3c4 \uc54a\uc744\ubfd0</a>\ub354\ub7ec IntersectionObserver\uac00 \ud2b8\ub9ac\uac70 \ub41c \ud6c4\uc5d0 image\ub97c \ub85c\ub529\ud558\uae30 \ub54c\ubb38\uc5d0 \uc801\uc6a9\ud558\uc9c0 \ub9c8\ub77c\ub77c\ub294 \uc774\uc57c\uae30\uc785\ub2c8\ub2e4. <a href=\\"https://docs.google.com/document/d/1jF1eSOhqTEt0L1WBCccGwH9chxLd9d1Ez0zo11obj14/edit#heading=h.vmietssik6ax\\">IntersectionObserver\uac00 native lazy loading\uc5d0\ub3c4 \uc4f0\uc774\ub294 \uac83</a>\uc774 \uc2e0\uae30\ud55c \uc810\uc774\ub124\uc694.</p><p data-notion-block-id=\\"a33ac17f-361f-4fe3-a339-1c440332dd7f\\"><b>\ucd5c\uc6d0\ube48</b>: <code>React.memo</code>\uc5d0 \ub300\ud55c \uae00\uc744 \ubcfc \ub54c\ub3c4 \ub290\ub080 \uac74\ub370, <b>\uc5b4\ub5a4 \uc0c1\ud669\uc774\ub358 \uc4f0\uae30\ub9cc \ud558\uba74 \uc131\ub2a5\uc774 \uc88b\uc544\uc9c0\ub294 \ub9c8\ubc95 \uac19\uc740 \uae30\ub2a5\uc740 \uc5c6\ub2e4</b>\ub294 \uac83\uc744 \ub610 \ub290\ub07c\ub124\uc694.(\uc788\ub2e4\uba74 default \ud504\ub85c\ud37c\ud2f0\uac00 \ub410\uaca0\uc8e0?) \ub300\ubd80\ubd84\uc758 \uc0c1\ud669\uc5d0\uc11c \uc774\uc810\uc744 \uc5bb\uc744 \uc21c \uc788\uc5b4\ub3c4, \ubaa8\ub974\uace0 \uc4f4\ub2e4\uba74 \uc190\ud574\ub97c \ubcfc \uc218 \uc788\ub2e4\ub294 \uc810\uc5d0 \uc720\uc758\ud558\ub3c4\ub85d \ud574\uc694.</p><p data-notion-block-id=\\"bfb30559-0abe-4a52-b4cc-0a748356498c\\"><b>\uae40\ub300\uad00</b>: \ud654\uba74\uc744 \ud1b5\ud574 \uc0ac\uc6a9\uc790\ub4e4\uc5d0\uac8c \ub354 \uc88b\uc740 \uc11c\ube44\uc2a4 \uacbd\ud5d8\uc744 \uc918\uc57c\ud558\ub294 \ud504\ub860\ud2b8\uc5d4\ub4dc \uac1c\ubc1c\uc790\ub4e4\uc774 \ud56d\uc0c1 \uace0\ubbfc\ud574\ub46c\uc57c\ud560 \uc774\ubbf8\uc9c0 \ub85c\ub529\ubb38\uc81c\ub97c \uc124\uba85\ud574\uc8fc\uace0 \uc788\ub124\uc694. lazy loading\uc744 \ud1b5\ud574 \uc131\ub2a5\uc744 \ud5a5\uc0c1\uc2dc\ucf30\ub2e4\uace0 \uc0dd\uac01\ud560 \uc218 \uc788\uc9c0\ub9cc, \uc2e4\uc81c\ub85c\ub294 \uc131\ub2a5\ub3c4 \uc81c\ub300\ub85c \ubabb \ucc59\uae30\uace0 UX\ub9c8\uc800 \uc800\ud558\ub420 \uc218\ub3c4 \uc788\ub2e4\ub294 \uc0ac\uc2e4\uc744 \ubc30\uc6cc\uac11\ub2c8\ub2e4.</p><h2 data-notion-block-id=\\"fcfdcca5-982c-4012-ba9b-5dc37122214a\\" id=\\"fcfdcca5-982c-4012-ba9b-5dc37122214a\\">\uc81c IDE/CI\uac00 \ub290\ub824\uc694: \ud0c0\uc785\uc2a4\ud06c\ub9bd\ud2b8</h2><a href=\\"https://www.youtube.com/watch?v=lJ63-j0OHG0\\" class=\\"bookmark-link\\" target=\\"_blank\\" rel=\\"noreferrer\\">https://www.youtube.com/watch?v=lJ63-j0OHG0</a><p data-notion-block-id=\\"a9a81b66-ecf7-47eb-a7b8-800e7a261c44\\"><b>\uc2ec\uc724\uc12d</b>: DX\uac00 \ub098\uc05c \uac83\uc740 \uc11c\ube44\uc2a4\uc5d0\ub3c4 \uc601\ud5a5\uc744 \ubbf8\uce69\ub2c8\ub2e4. HMR\uc774 \uc0dd\uae34 \uc774\ud6c4\ub85c HMR\uc774 \uc548\ub418\uba74 \ubd88\ud3b8\ud574\ud558\uba74\uc11c \ud574\ub2f9 \uae30\uc220\uc744 \ud3ec\uae30\ud560\uc815\ub3c4\ub85c\uc694. \uc774 \uc601\uc0c1\uc740 TypeScript\uc758 \ud0c0\uc785 \uccb4\ud06c/\ube4c\ub4dc\uac00 \ub290\ub9b0 \ubcf4\ud3b8\uc801\uc778 \uc774\uc720\uc640 \ud0d0\uc9c0 \ubc0f \ud574\uacb0\ubc29\ubc95\uc744 \uc54c\ub824\uc90d\ub2c8\ub2e4. \\"<code>swc</code>\ub098 <code>esbuild</code>\ub97c \uc4f0\uba74 \ube60\ub974\uc9c0 \uc54a\ub098\uc694?\\"\ub77c\uace0 \ub9d0\ud558\uc2e0\ub2e4\uba74 \ud2b8\ub79c\uc2a4\ud30c\uc77c \uc18d\ub3c4\ub9cc \ube60\ub974\uac8c \ud574\uc904 \ubfd0 \ud0c0\uc785 \uccb4\ud06c\ub97c \ud574\uc8fc\uc9c0 \uc54a\uc73c\ubbc0\ub85c \uc544\uc9c1\uc740 \ucd94\uc801 \ud6c4 \ub290\ub9b0 \uc774\uc720\ub97c \ucc3e\ub294 \ubc29\ubc95\ubc16\uc5d0 \uc5c6\uc73c\ubbc0\ub85c \uc774 \uc601\uc0c1\uc5d0\uc11c \ub9d0\ud558\ub294 \uc8fc\uc758\ud574\uc57c \ud560 \uc810\uc744 \uc54c\uace0 \uacc4\uc2dc\uba74 \uc88b\uc744\uac83 \uac19\uc2b5\ub2c8\ub2e4!</p><p data-notion-block-id=\\"52286d80-9710-4d99-b26f-1dcbfe752043\\"><b>\uae40\ub300\uad00</b>: \ud574\ub2f9 \uc601\uc0c1\uc5d0\uc11c\ub294 \ud0c0\uc785\uc2a4\ud06c\ub9bd\ud2b8\uc758 \ube4c\ub4dc\uac00 \ub290\ub9b0 \uc774\uc720\ub97c \uc54c\ub824\uc8fc\uba74\uc11c \ud0c0\uc785\uc2a4\ud06c\ub9bd\ud2b8\uc758 \ucef4\ud30c\uc77c\ub7ec\uac00 \ub3d9\uc791\ud558\ub294 \ubc29\uc2dd\uc744 \uc9da\uc5b4\uc8fc\uba70 \ud480\uc5b4\uc8fc\ub294 \uc720\uc775\ud55c \ubc1c\ud45c \uc601\uc0c1\uc785\ub2c8\ub2e4. \ud2b9\ubcc4\ud558\uac8c \ube4c\ub4dc\uac00 \ub290\ub9ac\uc9c0 \uc54a\ub2e4\ub294 \uac83\uc744 \uccb4\uac10\ud558\uc9c0 \ubabb\ud588\ub354\ub77c\ub3c4, \ud574\ub2f9 \uc601\uc0c1\uc5d0\uc11c \ud0c0\uc785\uc2a4\ud06c\ub9bd\ud2b8 \ucef4\ud30c\uc77c\ub7ec\uac00 \uc5b4\ub5bb\uac8c \ub3d9\uc791\ud558\ub294\uc9c0, \uae30\uc220\uc801\uc73c\ub85c \uc5b4\ub5bb\uac8c \ud574\uacb0\ud560 \uc218 \uc788\ub294\uc9c0\ub97c \uc27d\uac8c \uc54c\uc544 \uac08 \uc218 \uc788\uc2b5\ub2c8\ub2e4.</p><h2 data-notion-block-id=\\"d97e235c-7dad-4ca7-ab73-91acb8f10219\\" id=\\"d97e235c-7dad-4ca7-ab73-91acb8f10219\\">\ubaa8\ub178\ub808\ud3ec \uc801\uc6a9\uae30: \ud76c\ub9dd\ud3b8</h2><a href=\\"https://medium.com/musinsa-tech/journey-of-a-frontend-monorepo-8f5480b80661\\" class=\\"bookmark-link\\" target=\\"_blank\\" rel=\\"noreferrer\\">https://medium.com/musinsa-tech/journey-of-a-frontend-monorepo-8f5480b80661</a><p data-notion-block-id=\\"479128d3-7927-4ff9-93fd-5538134f0838\\"><b>\uc2ec\uc724\uc12d</b>: \ubaa8\ub178\ub808\ud3ec\ub85c \uc804\ud658 \uc801\uc6a9\uae30\uc640 \uc801\uc6a9\uc744 \ud558\uac8c\ub418\uba74 \uc88b\uc740 \uc810\uc744 \uc4f4 \uae00\uc785\ub2c8\ub2e4. \ud76c\ub9dd\ud3b8\uc774\ub77c\uace0 \uc801\uc5b4\ub193\uc740 \uc774\uc720\ub294 \uc808\ub9dd\ud3b8\uc774 \ub530\ub85c \uc788\uc5b4\uc11c\ub294 \uc544\ub2d9\ub2c8\ub2e4. \ud558\uc9c0\ub9cc <a href=\\"https://engineering.ab180.co/stories/yarn-to-pnpm\\">\uc7a5\uc810\ub9cc \uc788\ub294 \uac83\uc740 \uc544\ub2c8\uae30 \ub54c\ubb38</a>\uc5d0 \ud56d\uc0c1 \ud300\uacfc\uc758 \ucda9\ubd84\ud55c \ub17c\uc758 \ub05d\uc5d0 \ubaa8\ub178\ub808\ud3ec\ub97c \ub3c4\uc785\ud558\uc2dc\uae38 \ubc14\ub78d\ub2c8\ub2e4. <a href=\\"https://www.atlassian.com/git/tutorials/git-subtree\\">git subtree</a>\ub97c \uc0ac\uc6a9\ud574\ub3c4 \ub418\uace0\uc694! \uc790\uc138\ud55c \uac83\uc740 <a href=\\"https://github.com/joelparkerhenderson/monorepo-vs-polyrepo\\">monorepo vs polyrepo</a> \uc640 <a href=\\"https://monorepo.tools/\\">Monorepo Explained</a>\ub97c \ucc38\uace0\ud558\uc138\uc694.</p><p data-notion-block-id=\\"2a9513b4-84e8-414b-9b97-c32196d70957\\"><b>\uae40\ub300\uad00</b>: \ud655\uc2e4\ud788 \ub808\ud3ec\uc9c0\ud1a0\ub9ac \ud558\ub098\uc529 \uc62e\uaca8\ub2e4\ub2c8\ub294 \uac83\uc740 \uc77c\uc774\ub77c\uace0 \uc0dd\uac01\ud569\ub2c8\ub2e4. \ud558\uc9c0\ub9cc \u201c\ub808\ud3ec\uc9c0\ud1a0\ub9ac \uac04\uc758 \uae30\ub2a5\uc774 \uc77c\uad00\ub418\uc9c0 \uc54a\ub2e4\uba74, git \uad00\ub9ac\uc5d0 \uc788\uc5b4\uc11c \ubaa8\ub178\ub808\ud3ec \uc0dd\uc131\uc740 \uc9c0\uc591\ud574\uc57c\ud558\ub294 \ubd80\ubd84\uc774 \uc544\ub2cc\uac00\u201d? \ub77c\ub294 \uc0dd\uac01\uc774 \ub4ed\ub2c8\ub2e4.</p><p data-notion-block-id=\\"31606522-6b32-43e5-ade6-cc554b1c5233\\"><b>\ucd5c\uc6d0\ube48</b>: \uc11c\ube44\uc2a4\ub97c \ud655\uc7a5\ud558\ub2e4 \ubcf4\uba74 \ubc18\ub4dc\uc2dc \ub2e4\ub978 \ub3c4\uba54\uc778\uc758 \ub85c\uc9c1\uc744 \uac00\uc838\uc624\uac70\ub098, \ub3d9\uc77c\ud55c \ud568\uc218\ub97c \ud638\ucd9c\ud574\uc57c \ud560 \uc77c\uc774 \uc0dd\uae41\ub2c8\ub2e4. \uac19\uc740 \ubaa8\ub378\uc744 \uacf5\uc720\ud558\ub294 \uc77c\uc740 \ub354\uc6b1 \ud754\ud558\uc8e0. \ubaa8\ub178\ub808\ud3ec\ub294 \uc774\ub7f0 \uacbd\uc6b0\uc5d0 \uc815\ub9d0 \uc720\uc6a9\ud569\ub2c8\ub2e4! \ub2e4\ub9cc \ubaa8\ub178\ub808\ud3ec \uc801\uc6a9 \uc2dc \uacf5\ud1b5 \ubaa8\ub4c8 \ubd80\ubd84\uc740 \uc0ac\uc774\uc988\uac00 \ucee4\uc9c8 \uc218\ub85d \uc218\uc815\ud558\uae30 \ud798\ub4e4\uc5b4\uc9c0\uae30\uc5d0 \ub808\uac70\uc2dc\uac00 \ub420 \uc218 \uc788\ub294\ub370, \uc774\ub7f4 \ub54c \uc5ec\ub7ec \ud504\ub85c\uc81d\ud2b8\ub97c \ub3d9\uc2dc\uc5d0 \uc218\uc815\ud574\uc57c\ud558\ub2e4\ubcf4\ub2c8 \uac74\ub4e4\uae30 \ud798\ub4e4\uc5b4\uc9c0\ub294 \uacbd\uc6b0\uac00 \ub9ce\uc73c\ub2c8 \ub354 \ubd88\uc5b4\ub098\uae30 \uc804\uc5d0 \uc8fc\uae30\uc801\uc73c\ub85c \ud574\uc18c\ud558\ub294 \uac83\uc774 \uc911\uc694\ud569\ub2c8\ub2e4.</p><h2 data-notion-block-id=\\"301041ff-7308-4546-8b26-5cb5dade356f\\" id=\\"301041ff-7308-4546-8b26-5cb5dade356f\\">\uc778\ud130\ub809\uc158 \ub123\uae30\uc5d0 24\uc2dc\uac04\uc774 \ubaa8\uc790\ub77c</h2><a href=\\"https://toss.tech/article/interaction\\" class=\\"bookmark-link\\" target=\\"_blank\\" rel=\\"noreferrer\\">https://toss.tech/article/interaction</a><p data-notion-block-id=\\"c299739d-2b9f-4a30-b2de-bd6459226f07\\"><b>\uc2ec\uc724\uc12d</b>: \ud1a0\uc2a4\uc758 \ub514\uc790\uc778 \ucee8\ud37c\ub7f0\uc2a4\uc778 <a href=\\"https://simplicity-23.toss.im/\\">simplicity 23</a>\uc758 \uc138\uc158 \uc911 \ud558\ub098\uc778 \uc778\ud130\ub809\uc158\uc5d0 \ub300\ud55c \uc138\uc158\uc785\ub2c8\ub2e4. \ubcf4\ud1b5 \ub514\uc790\uc774\ub108\uac00 \uc2e0\uacbd\uc368\uc57c \ud558\ub294 \ubd80\ubd84\uc778 \uc778\ud130\ub809\uc158\uc744 \uac00\uc838\uc628 \uc774\uc720\ub294 \uacb0\uad6d FE \uac1c\ubc1c\uc790\uac00 \uc774 \ubd80\ubd84\uc744 \uad6c\ud604\ud574\uc57c \ud558\uae30 \ub54c\ubb38\uc5d0 \u201c\ubaa9\uc801\uc774 \ud655\uc2e4\ud558\ub2e4\uba74 \uc778\ud130\ub809\uc158\uc5d0 \uc560\ub2c8\uba54\uc774\uc158\uc744 \ub123\ub294 \uac83\uc774 \uc88b\ub2e4.\u201d\uc640 \u201c\uae30\uc874 \uc2dc\uc2a4\ud15c\uc5d0 \ubc18\ud558\ub294 \uc2dc\uc2a4\ud15c\uc744 \ub9cc\ub4e0\ub2e4\uba74 \uc27d\uac8c \uc0ac\uc6a9\ud560 \uc218 \uc788\ub294 \uac83\uc5d0 \ucd08\uc810\uc744 \ub9de\ucdb0\ub77c\u201d\ub294 \ubd80\ubd84\uc774 \uc640\ub2ff\uc544\uc11c \uac00\uc838\uc654\uc2b5\ub2c8\ub2e4. \ub514\uc790\uc774\ub108\uac00 \uc560\ub2c8\uba54\uc774\uc158\uc744 \ub9cc\ub4e4 \ub54c \uc870\uc5b8\uc744 \ud574\uc904 \uc218\ub3c4 \uc788\uad6c\uc694 \ud83d\ude0a</p><h2 data-notion-block-id=\\"5e9bc76c-4450-4587-92ba-77309d153537\\" id=\\"5e9bc76c-4450-4587-92ba-77309d153537\\">\uc138\ubc00\ud55c \ubc18\uc751\ud615 \ud504\ub85c\uadf8\ub798\ubc0d \uc54c\uc544\ubcf4\uae30</h2><a href=\\"https://frontendmasters.com/blog/vanilla-javascript-reactivity/\\" class=\\"bookmark-link\\" target=\\"_blank\\" rel=\\"noreferrer\\">https://frontendmasters.com/blog/vanilla-javascript-reactivity/</a><p data-notion-block-id=\\"d91fa04d-393d-4917-b2fd-a898f4ba429c\\">\u2192 <a href=\\"https://ktseo41.github.io/blog/log/patterns-for-reactivity-with-modern-vanilla-javascript.html\\">\ud55c\uad6d\uc5b4 \ubc88\uc5ed</a></p><p data-notion-block-id=\\"21af1ed3-08e3-4421-aad2-a94dc82945e9\\"><b>\uc2ec\uc724\uc12d</b>: Reactivity\ub77c\uace0 \uc4f4 \uc774\uc720\ub294 Reactive Programming\uc744 \ub9d0\ud558\ub824\ub294\uac8c \uc544\ub2c8\ub77c \ud504\ub860\ud2b8\uc5d4\ub4dc \ud328\ud0a4\uc9c0 \uc804\ubc18\uc5d0 \uc788\ub294 <a href=\\"https://indepth.dev/posts/1269/finding-fine-grained-reactive-programming\\">Fine-Grained Reactive Programming</a>\uc744 \uc0b4\ud3b4\ubcf4\uae30 \uc704\ud568\uc785\ub2c8\ub2e4. \uc2e4\ubb34\uc5d0 \ubc14\ub85c \uc801\uc6a9\ud560 \uc218 \uc788\ub294 \uc88b\uc740 \uc815\ubcf4\ub77c\uace0 \uc0dd\uac01\ub418\uc9c0\ub294 \uc54a\uc9c0\ub9cc \ubcf5\uc7a1\ud55c \uc2dc\uc2a4\ud15c\uc744 \ub9cc\ub4e4 \ub54c \ud55c \ubc88 \uc0dd\uac01\ud574\ubcfc \ub9cc\ud55c \ud328\ud134\ub4e4\uc785\ub2c8\ub2e4.</p><p data-notion-block-id=\\"c53e2630-dc2c-45da-a304-15673c24b173\\"><b>\ucd5c\uc6d0\ube48</b>: \ubc14\ub2d0\ub77c \uac1c\ubc1c\uc744 \ud560 \ub54c \uc720\uc6a9\ud55c \ud328\ud134\uacfc \uae30\uc220\ub4e4\uc774 \uc798 \uc815\ub9ac\ub418\uc5b4\uc788\uc2b5\ub2c8\ub2e4. <code>Observable-ish</code>\ub294 \uc0dd\uc18c\ud558\uc9c0\ub9cc \uc778\uc0c1\uc801\uc774\ub124\uc694. \uc0ac\uc2e4 \uc720\uc6a9\ud558\ub2e4\uae30\ubcf4\ub2e8 \uacf5\ubd80\uac00 \ub418\ub294 \ud328\ud134\ub4e4\uc5d0 \uac00\uae5d\uc9c0\ub9cc, \uc5b8\uc820\uac04 \ud55c\ubc88\ucbe4\uc740 \ubcf5\uc7a1\ud55c \uad6c\ud604\uccb4\ub97c \ub9cc\ub4e4\uc5b4\uc57c \ud560 \ub0a0\uc774 \uc624\uc9c0 \uc54a\uc744\uae4c\uc694? \ubbf8\ub9ac \uc54c\uc544\ub454\ub2e4\uba74 \uadf8 \ub0a0\uc5d0 \ub2e4\uc591\ud55c \ubc29\ud5a5\uc73c\ub85c \uc544\uc774\ub514\uc5b4\ub97c \ub0bc \uc218 \uc788\uc744\uac70\uc608\uc694!</p>"}')}}]);